#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

int parse_positive(const char *text, long *result) {
    char *end = NULL; errno = 0;
    long value = strtol(text, &end, 10);
    if (text == end || *end != '\0' || errno != 0 || value <= 0) return 0;
    *result = value; return 1;
}

int main(void) {
    long value;
    if (!parse_positive("42", &value)) return EXIT_FAILURE;
    printf("value = %ld\n", value);
    return EXIT_SUCCESS;
}
